const SESSION_TIMEOUT_MS = 30 * 60 * 1000;

/**
 * REQ-AUTH-002: Sessions expire when 30 minutes have elapsed since
 * lastActivityAt. Per ADR-001, the boundary at exactly 30 minutes counts
 * as expired.
 */
export function isSessionExpired(session: Session, now: number): boolean {
  return now - session.lastActivityAt >= SESSION_TIMEOUT_MS;
}

/**
 * Returns the number of milliseconds remaining until the existing
 * 30-minute session timeout, clamped to zero once the session has
 * expired. Does not read the system clock; callers must supply `now`.
 */
export function remainingSessionMs(session: Session, now: number): number {
  const remaining = SESSION_TIMEOUT_MS - (now - session.lastActivityAt);
  return remaining > 0 ? remaining : 0;
}

